INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6401, 'Judges 12:1', 'Judges', 12, 1, '&nbsp;د اِفرائيم سړى د جنګ دپاره تيار شول، هغوئ د اُردن سيند نه صفون ته پورې وتل او اِفتاح ته يې ووئيل، ”تۀ د عمونيانو سره جنګ دپاره د حد پولې نه ولې واوړېدلې او مونږ دې راونۀ غوښتلو چې تا سره لاړ شُو؟ مونږ به ستا کور سره تا وسوزوو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6402, 'Judges 12:2', 'Judges', 12, 2, '&nbsp;خو اِفتاح هغوئ ته ووئيل، ”زما او زما د خلقو د عمونيانو سره يوه سخته لانجه وه. ما تاسو راوغوښتلئ، خو تاسو زۀ د هغوئ نه بچ نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6403, 'Judges 12:3', 'Judges', 12, 3, '&nbsp;کله چې ما ته پته ولګېده چې تاسو زما د بچ کولو دپاره رانۀ غلئ، نو ما خپل ژوند په خطره کښې واچولو او د حد پولې نه واوړېدم چې د هغوئ سره جنګ وکړم او مالِک خُدائ ما له په هغوئ باندې فتح راکړه. نو اوس تاسو ما سره جنګ کولو له ولې راغلى يئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6404, 'Judges 12:4', 'Judges', 12, 4, '&nbsp;بيا اِفتاح د جِلعاد ټول سړى راغونډ کړل، د اِفرائيم د سړو سره يې جنګ وکړو او هغوئ له يې شکست ورکړو ځکه چې د اِفرائيم خلقو وئيلى وُو چې، ”تاسو جِلعاديان تش د اِفرائيم او منسى مفروران يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6405, 'Judges 12:5', 'Judges', 12, 5, '&nbsp;د دې دپاره چې اِفرائيميان تښتېدو ته پرې نۀ ږدى، جِلعاديانو هغه ځايونه ونيول چې چرته هغوئ د اُردن نه پورې وتلے شول. کله چې به يو اِفرائيمى هم د تښتېدو کوشش کولو نو هغۀ به د پورې وتو اجازت غوښتو او د جِلعاد سړو به ترې نه تپوس کولو، ”تۀ د اِفرائيم د قبيلې يې څۀ؟“ کۀ هغۀ به ووئيل چې، ”نه،“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6406, 'Judges 12:6', 'Judges', 12, 6, '&nbsp;هغوئ به ورته ووئيل چې، ”شبوليت ووايه.“ خو هغۀ به ورته په جواب کښې ”سبوليت“ ووئيل ځکه چې هغۀ به دا ټکے صحيح نۀ شو وئيلے. نو هغه به يې ونيولو او د اُردن سيند نه د پورې وتو په ځائ کښې به يې ووژلو. په هغه وخت کښې دوه څلوېښت زره اِفرائيميان ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6407, 'Judges 12:7', 'Judges', 12, 7, '&nbsp;اِفتاح شپږ کاله د بنى اِسرائيلو قاضى وو. بيا هغه مړ شو او په جِلعاد کښې په يو ښار کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6408, 'Judges 12:8', 'Judges', 12, 8, '&nbsp;د اِفتاح نه پس، د بيت‌لحم اِبصان د بنى اِسرائيلو قاضى شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6409, 'Judges 12:9', 'Judges', 12, 9, '&nbsp;د هغۀ دېرش زامن او دېرش لوڼه وې. هغۀ خپلې لوڼه د خپلې قبيلې نه بهر وادۀ کړې او خپلو زامنو له يې دېرش ښځې د پردو قبيلو نه وادۀ کړې. اِبصان اووۀ کاله د بنى اِسرائيلو قاضى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6410, 'Judges 12:10', 'Judges', 12, 10, '&nbsp;بيا هغه مړ شو او په بيت‌لحم کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6411, 'Judges 12:11', 'Judges', 12, 11, '&nbsp;د اِبصان نه پس، د زبولون ايلون لس کاله د بنى اِسرائيلو قاضى شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6412, 'Judges 12:12', 'Judges', 12, 12, '&nbsp;بيا هغه مړ شو او د زبولون په علاقه په ايالون کښې ښخ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6413, 'Judges 12:13', 'Judges', 12, 13, '&nbsp;د ايلون نه پس، د فِرعاتون نه د هليل زوئ عبدون د بنى اِسرائيلو قاضى شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6414, 'Judges 12:14', 'Judges', 12, 14, '&nbsp;د هغۀ څلوېښت زامن او دېرش نمسى وُو، چې هر يو په خپل خر باندې سورلى کوله. عبدون اتۀ کاله د بنى اِسرائيلو قاضى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6415, 'Judges 12:15', 'Judges', 12, 15, '&nbsp;بيا هغه مړ شو او په فِرعاتون کښې ښخ شو چې دا ځائ د عماليقيانو د غرونو په مُلک کښې د اِفرائيم په علاقه کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6416, 'Judges 13:1', 'Judges', 13, 1, '&nbsp;بنى اِسرائيلو د مالِک خُدائ خِلاف بيا ګناه وکړه، نو هغۀ فلستيان پرېښودل چې څلوېښت کاله پرې حکومت وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6417, 'Judges 13:2', 'Judges', 13, 2, '&nbsp;په هغه وخت کښې د صُرعا په ښار کښې د دان قبيلې يو سړے وو چې نوم يې منوحه وو، د هغۀ ښځه شنډه وه او بچى يې نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6418, 'Judges 13:3', 'Judges', 13, 3, '&nbsp;د مالِک خُدائ فرښته هغې ته راڅرګنده شوه او ورته يې وفرمائيل، ”تۀ هيڅکله د بچو د پېدا کېدو جوګه شوې نۀ يې، خو تۀ به زر اُميدواره شې او يو زوئ به دې وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6419, 'Judges 13:4', 'Judges', 13, 4, '&nbsp;خيال کوه چې مے يا شراب ونۀ څښې او نۀ چې حرام څيز وخورې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6420, 'Judges 13:5', 'Judges', 13, 5, '&nbsp;او ستا د زوئ پېدا کېدو نه پس هيڅکله چې د هغۀ وېښتۀ پرې نۀ کړې، ځکه چې د هغۀ د پېدا کېدو د ورځې نه به هغه خُدائ پاک ته د نذير په حيثيت وقف وى. هغه به د فلستيانو نه د بنى اِسرائيلو بچ کول شروع کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6421, 'Judges 13:6', 'Judges', 13, 6, '&nbsp;بيا هغه ښځه لاړه او خپل خاوند ته يې ووئيل، ”د خُدائ پاک يو سړے ما له راغلو، هغه د خُدائ پاک د فرښتې په شان هيبتناک ښکارېدو. ما د هغۀ نه تپوس ونۀ وکړو چې د کوم ځائ نه راغلے يې، نو هغۀ ما ته خپل نوم هم ونۀ ښودلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6422, 'Judges 13:7', 'Judges', 13, 7, '&nbsp;خو هغۀ ما ته وفرمائيل چې زۀ به اُميدواره شم او يو زوئ به مې وشى. هغۀ راته وفرمائيل چې مے يا شراب مۀ څښه او نۀ چې حرام څيز وخورې، ځکه چې تر کومې پورې هغه ماشوم ژوندے وى نو هغه به خُدائ پاک ته د نذير په حيثيت وقف وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6423, 'Judges 13:8', 'Judges', 13, 8, '&nbsp;نو منوحه مالِک خُدائ ته سوال وکړو، ”مالِکه خُدايه، د خُدائ پاک هغه سړے کوم چې تا رالېږلے وو هغه پرېږده چې بيا مونږ له راشى او مونږ ته وښائى چې کله هغه هلک پېدا شى نو مونږ د هغۀ سره څۀ وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6424, 'Judges 13:9', 'Judges', 13, 9, '&nbsp;منوحه چې کوم سوال کړے وو نو خُدائ پاک هم هغه شان وکړل او چې کله هغه ښځه په پټو کښې ناسته وه نو د خُدائ پاک هغه فرښته ورله واپس راغله، خو د هغې خاوند منوحه د هغې سره نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6425, 'Judges 13:10', 'Judges', 13, 10, '&nbsp;نو هغې سمدستى منډه کړه او خپل خاوند ته يې ووئيل، ”ګوره، هغه بله ورځ چې کوم سړے ما له راغلے وو هغه بيا ما ته څرګند شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6426, 'Judges 13:11', 'Judges', 13, 11, '&nbsp;منوحه پاڅېدو او خپلې ښځې پسې لاړو. هغه سړى له ورَغلو او تپوس يې ترې نه وکړو، ”آيا تۀ هغه سړے يې څۀ چا چې زما د ښځې سره خبرې کولې؟“ هغۀ جواب ورکړو، ”آو، زۀ هم هغه يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6427, 'Judges 13:12', 'Judges', 13, 12, '&nbsp;نو منوحه ترې نه تپوس وکړو، ”کله چې ستا خبره رښتيا شى، نو د هغه هلک د ژوند اصُول به څۀ وى او د هغۀ کار به څۀ وى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6428, 'Judges 13:13', 'Judges', 13, 13, '&nbsp;د مالِک خُدائ فرښتې ورته وفرمائيل، ”ستا ښځه به دا خبره يقينى کړى چې هغه هر څۀ وکړى چې څۀ ما ورته وئيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6429, 'Judges 13:14', 'Judges', 13, 14, '&nbsp;هغه به داسې يو څيز هم نۀ خورى چې د انګورو باغ نه راځى، هغه به يو قِسم مے هم نۀ څښى او نۀ به حرام څيز خورى. هغه به خامخا هغه هر څۀ کوى چې ما ورته وئيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6430, 'Judges 13:17', 'Judges', 13, 17, '&nbsp;منوحه ورته ووئيل، ”مونږ ته خپل نوم وښايه، چې کله ستا خبره رښتيا شى نو مونږ به ستا عزت وکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6431, 'Judges 13:18', 'Judges', 13, 18, '&nbsp;فرښتې ورته وفرمائيل، ”تۀ زما د نوم تپوس ولې کوې؟ دا يو داسې عجيبه نوم دے چې تۀ به ورباندې پوهه نۀ شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6432, 'Judges 13:19', 'Judges', 13, 19, '&nbsp;نو منوحه د چېلۍ يو بچے او څۀ غله واخستله او د ګټ په قربان‌ګاه باندې يې مالِک خُدائ ته پېش کړه. او چې کله منوحه او د هغۀ ښځې ورته کتل نو مالِک خُدائ يو عجيبه کار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6433, 'Judges 13:22', 'Judges', 13, 22, '&nbsp;منوحه خپلې ښځې ته ووئيل، ”په دې کښې څۀ شک نشته چې مونږ به مړۀ شُو، ځکه چې مونږ خُدائ پاک ليدلے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6434, 'Judges 13:23', 'Judges', 13, 23, '&nbsp;خو ښځې يې جواب ورکړو، ”کۀ مالِک خُدائ زمونږ وژل غوښتلے، نو هغۀ به هيڅکله زمونږ نذرانې نۀ قبلولې، نو هغۀ به مونږ ته دا هر څۀ نۀ ښودلے او نۀ به يې راته دا خبرې کړې وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6435, 'Judges 13:24', 'Judges', 13, 24, '&nbsp;نو د هغۀ د ښځې يو زوئ وشو او سمسون نوم يې ورباندې کېښودو. هغه ماشوم لوئېدو او مالِک خُدائ برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6436, 'Judges 13:25', 'Judges', 13, 25, '&nbsp;او د مالِک خُدائ روح هغه په هغه وخت کښې تکړه کړو چې کله هغه د صُرعا او اِستال په مينځ کښې د دان په کېمپ کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6437, 'Judges 14:1', 'Judges', 14, 1, '&nbsp;يوه ورځ سمسون تمنت ته لاړو، هلته يې يوه پېغله فلستى وليده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6438, 'Judges 14:2', 'Judges', 14, 2, '&nbsp;هغه واپس کور ته لاړو او خپل مور پلار ته يې وفرمائيل، ”په تمنت کښې ما يوه فلستى جينۍ ليدلې ده او اوس هغه ما ته وادۀ کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6439, 'Judges 14:3', 'Judges', 14, 3, '&nbsp;خو مور پلار يې ورته ووئيل، ”ستا په خپلوانو يا زمونږ په ټولو خلقو کښې جينۍ نشته څۀ، چې تۀ خامخا ځې او په ناسنته فلستيانو کښې جينۍ کوې؟“ خو سمسون خپل پلار ته وفرمائيل، ”هغه جينۍ ما له وکړه ځکه چې هغه مې خوښه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6440, 'Judges 14:4', 'Judges', 14, 4, '&nbsp;مور پلار ته يې دا پته نۀ وه چې په دې کار کښې د مالِک خُدائ لاس وو، ځکه چې مالِک خُدائ د فلستيانو سره د جنګ دپاره يوه موقع لټوله. په هغه وخت کښې فلستيانو په بنى اِسرائيلو باندې حکومت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6441, 'Judges 14:5', 'Judges', 14, 5, '&nbsp;نو سمسون د خپل مور پلار سره تمنت ته لاړو. کله چې هلته هغوئ د انګورو په باغونو کښې تېرېدل، هغۀ آواز واورېدو چې يو ځوان زمرے هغۀ ته مخامخ غوريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6442, 'Judges 14:6', 'Judges', 14, 6, '&nbsp;د مالِک خُدائ روح ناڅاپه په هغۀ نازل شو او سمسون يې تکړه کړو او په تشو لاسونو يې زمرے ټوټې ټوټې کړو، لکه چې دا د چېلۍ بچے وى. خو هغۀ خپل مور پلار ته د دې په حقله ونۀ وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6443, 'Judges 14:7', 'Judges', 14, 7, '&nbsp;بيا هغه لاړو او د هغه جينۍ سره يې خبرې وکړې او هغه يې خوښه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6444, 'Judges 14:8', 'Judges', 14, 8, '&nbsp;يو څو ورځې پس سمسون د هغې سره وادۀ کولو دپاره واپس لاړو. په لاره کښې هغه راوګرځېدو چې د هغه ازمرى لاش وګورى چې کوم يې وژلے وو او هغۀ وليدل چې د دې په لاش کښې دننه ډېرې مچۍ او شات هم وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6445, 'Judges 14:9', 'Judges', 14, 9, '&nbsp;هغۀ شات د لاسونو سره راوويستل او په روانه کښې يې خوړل. بيا هغۀ خپل مور او پلار له هم يوړل او لږ يې ترې نه ورکړل او هغوئ هم وخوړل، خو سمسون ونۀ فرمائيل چې دا شات يې د مړ ازمرى نه راويستلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6446, 'Judges 14:10', 'Judges', 14, 10, '&nbsp;د هغۀ پلار د هغه جينۍ کور ته لاړو او سمسون هلته لويه مېلمستيا وکړه. هلته د ځوانانو دا رِواج وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6447, 'Judges 14:11', 'Judges', 14, 11, '&nbsp;کله چې فلستيانو هغه وليدو، نو هغوئ دېرش ځوانان ملګرى ورولېږل چې د هغۀ سره ايسار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6448, 'Judges 14:14', 'Judges', 14, 14, '&nbsp;هغۀ ورته وفرمائيل، ”د خوړونکى نه د خوراک څۀ شے راووتلو، د تکړه شى نه څۀ خوږ شے راووتلو.“ درې ورځې وروستو هم هغوئ د دې سخت سوال جواب ورنۀ کړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6449, 'Judges 14:15', 'Judges', 14, 15, '&nbsp;په څلورمه ورځ هغوئ د سمسون ښځې ته ووئيل، ”خپل خاوند وغولوه چې مونږ ته د دې سخت سوال مطلب وښائى. کۀ تا ونۀ ښودلو نو مونږ به ستا د پلار په کور اور ولګوو او تا به هم په کښې وسوزوو. تا مونږ د دې دپاره راغوښتى يُو څۀ چې غريبانان شُو؟ کۀ داسې نۀ ده؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6450, 'Judges 14:16', 'Judges', 14, 16, '&nbsp;نو د سمسون ښځه په ژړا هغۀ له ورغله او ورته يې ووئيل، ”تۀ زما سره مينه نۀ کوې. تۀ زما نه کرکه کوې. تا زما د خلقو نه د سخت سوال تپوس وکړو او ما ته دې ونۀ وئيل چې د دې مطلب څۀ دے.“ هغۀ ورته وفرمائيل، ”ګوره، ما خپل مور پلار ته هم نۀ دى وئيلى. نو زۀ تا ته ولې ووايم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6451, 'Judges 14:17', 'Judges', 14, 17, '&nbsp;هغې د دې په حقله د خېرات په ټولو اوو ورځو کښې ژړل. خو په اوومه ورځ هغۀ ورته د دې سخت سوال مطلب وښودلو، ځکه چې هغې د دې په حقله هغه ډېر تنګ کړو. بيا هغې فلستيانو ته ووئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6452, 'Judges 14:18', 'Judges', 14, 18, '&nbsp;نو په اوومه ورځ د نمر پرېوتو نه مخکښې، د ښار سړو هغۀ ته ووئيل، ”د شاتو نه به خوږ څۀ شے وى؟ د ازمرى نه به تکړه څۀ شے وى؟“ سمسون ورته په جواب کښې وفرمائيل، ”کۀ تاسو زما په غوا يوې نۀ وے کړے، نو تاسو به د دې سخت سوال جواب نۀ وے راکړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6453, 'Judges 14:19', 'Judges', 14, 19, '&nbsp;د مالِک خُدائ روح ناڅاپه په هغۀ باندې راغلو او هغه يې تکړه کړو او هغه لاندې اسقلون ته لاړو، چرته چې يې دېرش سړى ووژل، جامې يې ترېنه وويستلې او د هغوئ جامې يې هغه سړو له ورکړې چا چې هغه سخت سوال حل کړے وو. د هغې نه پس هغه واپس د خپل پلار کور ته لاړو، چې څۀ شوى وُو په هغې باندې سخت غصه وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6454, 'Judges 14:20', 'Judges', 14, 20, '&nbsp;او د سمسون ښځه هغه سړى له ورکړے شوه چې کوم د هغۀ په وادۀ کښې د هغۀ ښۀ ملګرے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6455, 'Judges 15:1', 'Judges', 15, 1, '&nbsp;لږه موده وروستو سمسون د غنمو د لَو په وخت کښې د خپلې ښځې سره مِلاوېدو دپاره لاړو او يو د چېلۍ بچے يې ورله بوتلو. هغۀ د هغې پلار ته وفرمائيل، ”زۀ غواړم چې د خپلې ښځې کوټې ته لاړ شم او ورسره څملم.“ خو د هغې پلار هغه دننه نۀ پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6456, 'Judges 15:2', 'Judges', 15, 2, '&nbsp;هغۀ سمسون ته ووئيل، ”په حقيقت کښې زما خيال دا وو چې تۀ د هغې نه کرکه کوې، نو ما هغه ځکه ستا ښۀ ملګرى له ورکړه. خو کشره خور يې ترې نه ښائسته ده، د هغې په ځائ دا وکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6457, 'Judges 15:3', 'Judges', 15, 3, '&nbsp;سمسون وفرمائيل، ”دا ځل چې زۀ د فلستيانو سره څۀ کوم نو د هغې اِلزام دې په ما نۀ شى لګولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6458, 'Judges 15:4', 'Judges', 15, 4, '&nbsp;نو هغه لاړو او درې سوه لومبړې يې ونيولې. د دؤو دؤو لومبړو لکۍ يې وتړلې او د دې په غوټو کښې يې چراغونه کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6459, 'Judges 15:5', 'Judges', 15, 5, '&nbsp;بيا هغۀ چراغونه بل کړل او لومبړې يې د فلستيانو فصلونو طرف ته پرېښودلې. نو داسې هغه ګېډۍ شوے فصل او ولاړ فصل يې وسوزولو او د انګورو او زيتُونو باغونه يې هم ورسره وسوزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6460, 'Judges 15:6', 'Judges', 15, 6, '&nbsp;کله چې فلستيانو تپوس وکړو چې، ”دا چا کړى دى؟“ نو هغوئ خبر شول چې دا سمسون کړى دى، ځکه چې د تمنت يو سړى يعنې د هغۀ سخر، د سمسون ښځه د سمسون ملګرى له ورکړې وه. نو فلستيان لاړل او هغه ښځه او د هغې پلار يې په اور وسوزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6461, 'Judges 15:7', 'Judges', 15, 7, '&nbsp;سمسون هغوئ ته وفرمائيل، ”چې تاسو دا کار کړے دے نو په دې وجه زۀ قسم خورم چې تر هغې پورې به زۀ قلار نۀ شم چې ترڅو پورې مې ستاسو نه بدل نۀ وى اخستے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6462, 'Judges 15:8', 'Judges', 15, 8, '&nbsp;نو هغۀ په دوئ باندې سخته حمله وکړه او ډېر کسان يې ترې نه ووژل. بيا هغه لاړو او د ايتام غر په يو غار کښې ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6463, 'Judges 15:9', 'Judges', 15, 9, '&nbsp;فلستيان راغلل او په يهوداه کښې يې خېمې ولګولې او د لحى په ښار يې حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6464, 'Judges 15:10', 'Judges', 15, 10, '&nbsp;د يهوداه سړو د هغوئ نه تپوس وکړو، ”تاسو په مونږ باندې ولې حمله کوئ؟“ هغوئ په جواب کښې ورته ووئيل، ”مونږ د دې دپاره راغلى يُو چې سمسون قېدى بوځُو او هم هغه شان ورسره وکړُو چې څۀ يې زمونږ سره کړى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6465, 'Judges 15:11', 'Judges', 15, 11, '&nbsp;نو د يهوداه درې زره سړى د ايتام د غرۀ هغه غار ته لاړل او سمسون ته يې ووئيل، ”تا ته پته نشته څۀ چې فلستيان په مونږ باندې حکومت کوى؟ تا مونږ سره څۀ کړى دى؟“ هغۀ جواب ورکړو، ”ما د هغوئ سره هم هغه شان وکړل چې څۀ يې زما سره کړى وُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6466, 'Judges 15:12', 'Judges', 15, 12, '&nbsp;هغوئ ووئيل، ”مونږ دلته د دې دپاره راغلى يُو چې تا وتړُو، نو داسې به تا هغوئ ته په حواله کړُو.“ سمسون وفرمائيل، ”ما ته قسم وخورئ چې تاسو به په خپله ما نۀ وژنئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6467, 'Judges 15:13', 'Judges', 15, 13, '&nbsp;هغوئ ورته ووئيل، ”ټيک ده، مونږ به صِرف تا وتړُو او هغوئ ته به دې حواله کړُو. مونږ تا نۀ وژنو.“ نو هغوئ هغه په دؤو نوؤ پړو وتړلو او د غرۀ نه يې په زور بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6468, 'Judges 15:14', 'Judges', 15, 14, '&nbsp;کله چې هغه لحى ته راغلو، نو فلستيانو د هغۀ طرف ته منډې وهلې او هغۀ ته يې چغې وهلې. د مالِک خُدائ روح ناڅاپه هغه تکړه کړو، نو هغۀ د خپلو لاسونو او مټو نه تاو شوى پړى داسې وشلول لکه چې سوزېدلى تارونه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6469, 'Judges 15:15', 'Judges', 15, 15, '&nbsp;بيا هغۀ د خر د ژامنې يو تازه هډُوکے وموندو. هغه ورټيټ شو او راوچت يې کړو او زر سړى يې ورباندې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6470, 'Judges 15:16', 'Judges', 15, 16, '&nbsp;او هغۀ ووئيل، ”د خر د ژامنې هډُوکى سره ما زر سړى ووژل، د خر د ژامنې هډُوکى سره ما هغوئ ډېرے ډېرے کړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6471, 'Judges 15:17', 'Judges', 15, 17, '&nbsp;د هغې نه پس هغۀ د ژامنې هډُوکے وغورزولو. چرته چې دا کار وشو نو د هغه ځائ نوم د ژامنې غر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6472, 'Judges 15:18', 'Judges', 15, 18, '&nbsp;بيا سمسون سخت تږے شو، نو هغۀ مالِک خُدائ ته فرياد وکړو او وې فرمائيل، ”تا ما له دا لويه فتح راکړې ده، اوس زۀ د تندې نه مرم او د ناسنته په لاسونو کښې به وغورزېږم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6473, 'Judges 15:19', 'Judges', 15, 19, '&nbsp;نو خُدائ پاک هلته د لحى په زمکه کښې يو خالى ځائ کولاو کړو او اوبۀ ترې نه راووتلې. سمسون اوبۀ وڅښلې او تازه دم شو. نو هغۀ په دې باندې دا نوم کېښودو، ”د چغې وهونکى چينه“ او دا تر اوسه پورې په لحى کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6474, 'Judges 15:20', 'Judges', 15, 20, '&nbsp;د فلستيانو په دور کښې سمسون شل کاله د بنى اِسرائيلو قاضى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6475, 'Judges 16:1', 'Judges', 16, 1, '&nbsp;سمسون يوه ورځ فلستى ښار غزه ته لاړو، هلته د يوې کنجرې سره مِلاو شو او د هغې سره څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6476, 'Judges 16:2', 'Judges', 16, 2, '&nbsp;د غزه خلقو ته پته ولګېده چې سمسون هلته دے، نو هغوئ هغه ځائ نه ګېره واچوله او د ښار په دروازه کښې يې ټوله شپه د هغۀ اِنتظار وکړو. ټوله شپه هغوئ غلى وُو، د خپلو ځانونو سره يې دا سوچ کولو چې، ”د سحر رڼا پورې به مونږ اِنتظار وکړُو او بيا به هغه ووژنو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6477, 'Judges 16:3', 'Judges', 16, 3, '&nbsp;خو سمسون تر نيمې شپې پورې د کنجرې سره پروت وو. بيا هغه پاڅېدو او د ښار دروازه يې ونيوله او د تمبو، دُرشلو، تالو او هر څۀ سره يې وويستله. هغۀ دا په خپلو اوږو باندې کېښودل او د هغه غر سر پورې يې يوړل چرته نه چې حبرون ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6478, 'Judges 16:4', 'Judges', 16, 4, '&nbsp;د هغې نه پس، سمسون په يوه ښځه باندې مئين شو چې نوم يې دليله وو، چې هغه د سورِق په مېدان کښې اوسېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6479, 'Judges 16:5', 'Judges', 16, 5, '&nbsp;هغه پينځۀ فلستى بادشاهان هغې له لاړل او ورته يې ووئيل، ”سمسون وغولوه چې تا ته ووائى چې هغه دومره تکړه ولې دے او مونږ په هغۀ باندې څنګه غالِب راتلے شُو، چې وې تړُو او کمزورے يې کړُو. مونږ هر يو به تا له يوولس سوه د سپينو زرو سيکې درکړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6480, 'Judges 16:6', 'Judges', 16, 6, '&nbsp;نو دليلې سمسون ته ووئيل، ”مِهربانى وکړه ما ته ووايه چې تۀ په څۀ څيز دومره تکړه يې. کۀ څوک تا تړل او کمزورے کول وغواړى نو هغه داسې څنګه کولے شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6481, 'Judges 16:7', 'Judges', 16, 7, '&nbsp;سمسون ورته په جواب کښې وفرمائيل، ”کۀ هغوئ د ليندې په اوو نوؤ مزو باندې ما وتړى چې هغه تازه وى او اوچ شوى نۀ وى، نو زۀ به د نورو په شان کمزورے شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6482, 'Judges 16:8', 'Judges', 16, 8, '&nbsp;نو فلستى بادشاهانو دليلې له د ليندې اووۀ مزى راوړل چې اوچ شوى نۀ وُو او هغې پرې سمسون وتړلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6483, 'Judges 16:9', 'Judges', 16, 9, '&nbsp;په بله کوټه کښې د هغې څۀ سړو اِنتظار کولو، نو هغې چغه کړه، ”سمسونه، ستا د نيولو دپاره فلستيان راغلى دى.“ خو هغۀ د ليندې مزى داسې وشلول لکه چې په تارونو باندې اور ولګى او وشليږى. خو هغوئ ته بيا هم د هغۀ د طاقت د راز پته ونۀ لګېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6484, 'Judges 16:10', 'Judges', 16, 10, '&nbsp;دليلې سمسون ته ووئيل، ”ګوره، تا زما نه بې‌وقوفه جوړه کړې ده او ما ته دې دروغ ووئيل. اوس ما ته ووايه چې تۀ څنګه ښۀ تړلے کېدے شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6485, 'Judges 16:11', 'Judges', 16, 11, '&nbsp;هغۀ ورته وفرمائيل، ”کۀ هغوئ ما په داسې رسو باندې وتړى چې هيڅکله هم استعمال شوې نۀ وى، نو زۀ به د نورو په شان کمزورے شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6486, 'Judges 16:12', 'Judges', 16, 12, '&nbsp;نو دليلې نوې رسۍ راوړې او هغه يې پرې وتړلو. بيا هغې چغه کړه، ”سمسونه، ستا د نيولو دپاره فلستيان راغلى دى.“ هغه سړو په بله کوټه کښې اِنتظار کولو. نو هغۀ رسۍ د تارونو په شان د خپلو مټو نه وشلولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6487, 'Judges 16:13', 'Judges', 16, 13, '&nbsp;دليلې سمسون ته ووئيل، ”تا تر اوسه پورې زما نه کم عقله جوړه کړې ده او ما ته دروغ وائې. ما ته ووايه چې تۀ څنګه ښۀ تړلے کېدے شې.“ هغۀ ورته وفرمائيل، ”کۀ تۀ زما د وېښتو اووۀ کونسۍ د جامو په خپله کډۍ کښې وګنډې او د کډۍ په سيخ پورې يې وتړې، نو زۀ به د نورو په شان کمزورے يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6488, 'Judges 16:14', 'Judges', 16, 14, '&nbsp;دليلې هغه په آرام سره اودۀ کړو، د هغۀ د وېښتو اووۀ کونسۍ يې وګنډلې او د کډۍ په سيخ پورې يې وتړلې او چغه يې کړه، ”سمسونه، ستا د نيولو دپاره فلستيان راغلى دى.“ خو هغه پاڅېدو او خپل وېښتۀ يې د هغه کډۍ نه خلاص کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6489, 'Judges 16:15', 'Judges', 16, 15, '&nbsp;نو هغې ورته ووئيل، ”تۀ څنګه وائې چې زما سره مينه کوې، کله چې تۀ په ما اعتبار هم نۀ کوې؟ تا درې ځل زما نه کم عقله جوړه کړه او تا بيا هم ما ته ونۀ وئيل چې تۀ په څۀ باندې دومره تکړه يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6490, 'Judges 16:16', 'Judges', 16, 16, '&nbsp;هغې به هره ورځ د هغۀ نه تپوس کولو. هغې هغه دومره تنګ کړے وو چې پوزې له ترې راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6491, 'Judges 16:17', 'Judges', 16, 17, '&nbsp;نو سمسون آخر کښې هغې ته رښتيا وئيل، ”زما وېښتۀ هيڅکله هم نۀ دى کل شوى. زما د پېدا کېدو د وخت نه زۀ خُدائ پاک ته د نذير په حيثيت وقف يم. کۀ زما وېښتۀ کل شوى وے، نو زما طاقت به ختم شوے وو او د نورو په شان به کمزورے وم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6492, 'Judges 16:18', 'Judges', 16, 18, '&nbsp;کله چې دليلې ته پته ولګېده چې هغۀ ورته ټول راز وښودلو، نو هغې فلستى بادشاهانو ته يو پېغام ولېږلو او ورته يې ووئيل، ”تاسو يو ځل بيا راشئ. سمسون ما ته رښتيا وئيلى دى.“ نو هغوئ راغلل او د ځان سره يې پېسې هم راوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6493, 'Judges 16:19', 'Judges', 16, 19, '&nbsp;دليلې په آرام سره سمسون په خپل غېږ کښې اودۀ کړو او بيا يې سړے راوغوښتلو، چې هغۀ د سمسون د وېښتو اووۀ څڼې کلې کړې. نو داسې هغه يې په تکليف کښې واچولو ځکه چې د هغۀ طاقت ختم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6494, 'Judges 16:20', 'Judges', 16, 20, '&nbsp;بيا هغې چغه کړه، ”سمسونه، ستا د نيولو دپاره فلستيان راغلى دى.“ هغه پاڅېدو او خيال يې دا وو چې زۀ به د مخکښې په شان ځان خلاص کړم او آزاد به شم. خو هغۀ ته پته نۀ وه چې مالِک خُدائ هغه پرېښے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6495, 'Judges 16:21', 'Judges', 16, 21, '&nbsp;فلستيانو هغه ونيولو او سترګې يې ترې نه وويستلې. هغه يې غزه ته بوتلو او د زېړو په زنځيرونو باندې يې وتړلو او په قېد کښې ترې نه د مېچنې د تاوولو کار اخستلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6496, 'Judges 16:22', 'Judges', 16, 22, '&nbsp;خو د هغۀ وېښتۀ بيا راوشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6497, 'Judges 16:23', 'Judges', 16, 23, '&nbsp;فلستى بادشاهان راغونډ شول چې جشن وکړى او خپل خُدائ دجون ته يوه لويه قربانى پېش کړى. هغوئ ووئيل، ”زمونږ خُدائ مونږ له زمونږ په دشمن سمسون باندې فتح راکړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6498, 'Judges 16:26', 'Judges', 16, 26, '&nbsp;سمسون هغه هلک ته وفرمائيل چا چې لاس نيولے روان کړے وو چې، ”ما پرېږده چې په هغه ستنو باندې لاس ولګوم چې په کومو باندې دا کور ولاړ دے. زۀ په دې باندې تکيه لګول غواړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6499, 'Judges 16:27', 'Judges', 16, 27, '&nbsp;هغه ځائ د ښځو او سړو نه ډک وو. پينځۀ واړه فلستى بادشاهان هم هلته وُو او هلته په چت باندې تقريباً درې زره ښځې او سړى وُو، هغوئ کتل چې په سمسون پورې ټوقې کېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6500, 'Judges 16:28', 'Judges', 16, 28, '&nbsp;سمسون سوال وکړو، ”اے مالِکه خُدايه پاکه، لږ ما راياد کړه، خُدايه پاکه. زۀ تا ته سوال کوم چې يو ځل بيا ما له طاقت راکړه، نو چې په دې يو وار د فلستيانو نه د خپلو دوو سترګو بدل واخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');